integer","default":null,"notNull":true},{"name":"source_evidence","type":"jsonb","default":null,"notNull":true},{"name":"source_total","type":"integer","default":null,"notNull":true},{"name":"start_at","type":"timestamp with time zone","default":null,"notNull":true}],"indexes":[{"ready":true,"valid":true,"unique":false,"definition":"CREATE INDEX newar_detail_coverage_active_idx ON private.newar_detail_coverage_runs USING btree (platform, dataset, effective_start_at, end_at) WHERE (invalidated_at IS NULL)"},{"ready":true,"valid":true,"unique":false,"definition":"CREATE INDEX newar_detail_coverage_range_idx ON private.newar_detail_coverage_runs USING btree (platform, dataset, effective_start_at, end_at)"},{"ready":true,"valid":true,"unique":true,"definition":"CREATE UNIQUE INDEX newar_detail_coverage_runs_pkey ON private.newar_detail_coverage_runs USING btree (coverage_id)"}],"forceRls":false,"triggers":[],"qualified":"private.newar_detail_coverage_runs","constraints":[{"name":"newar_detail_coverage_runs_basis_check","validated":true,"definition":"CHECK ((basis = ''created''::text))"},{"name":"newar_detail_coverage_runs_check","validated":true,"definition":"CHECK (((start_at < end_at) AND (effective_start_at >= start_at) AND (effective_start_at < end_at) AND (end_at <= observed_at) AND ((end_at - start_at) <= ''36:00:00''::interval)))"},{"name":"newar_detail_coverage_runs_check1","validated":true,"definition":"CHECK ((source_total = (record_count + prelaunch_excluded)))"},{"name":"newar_detail_coverage_runs_dataset_check","validated":true,"definition":"CHECK ((dataset = ANY (ARRAY[''charge''::text, ''withdraw''::text, ''workorder''::text])))"},{"name":"newar_detail_coverage_runs_members_digest_check","validated":true,"definition":"CHECK ((length(members_digest) = 64))"},{"name":"newar_detail_coverage_runs_pkey","validated":true,"definition":"PRIMARY KEY (coverage_id)"},{"name":"newar_detail_coverage_runs_platform_fkey","validated":true,"definition":"FOREIGN KEY (platform) REFERENCES newar_detail_platforms(platform)"},{"name":"newar_detail_coverage_runs_record_count_check","validated":true,"definition":"CHECK ((record_count >= 0))"}]},{"acl":"{postgres=arwdDxtm/postgres}","oid":"324442","rls":true,"kind":"r","owner":"postgres","table":"newar_withdraw_facts","columns":[{"name":"account","type":"text","default":null,"notNull":true},{"name":"captured_at","type":"timestamp with time zone","default":null,"notNull":true},{"name":"created_at","type":"timestamp with time zone","default":null,"notNull":true},{"name":"currency","type":"text","default":null,"notNull":false},{"name":"handled_at","type":"timestamp with time zone","default":null,"notNull":false},{"name":"method","type":"text","default":null,"notNull":false},{"name":"platform","type":"text","default":null,"notNull":true},{"name":"received_at","type":"timestamp with time zone","default":null,"notNull":true},{"name":"record_id","type":"uuid","default":null,"notNull":true},{"name":"source_id","type":"text","default":null,"notNull":true},{"name":"status_group","type":"text","default":null,"notNull":true},{"name":"submitted_at","type":"timestamp with time zone","default":null,"notNull":false}],"indexes":[{"ready":true,"valid":true,"unique":false,"definition":"CREATE INDEX newar_withdraw_facts_platform_created_idx ON private.newar_withdraw_facts USING btree (platform, created_at)"},{"ready":true,"valid":true,"unique":true,"definition":"CREATE UNIQUE INDEX newar_withdraw_facts_pkey ON private.newar_withdraw_facts USING btree (record_id)"}],"forceRls":false,"triggers":[],"qualified":"private.newar_withdraw_facts","constraints":[{"name":"newar_withdraw_facts_method_check","validated":true,"definition":"CHECK ((method = ANY (ARRAY[''auto''::text, ''manual''::text])))"},{"name":"newar_withdraw_facts_pkey","validated":true,"definition":"PRIMARY KEY (record_id)"},{"name":"newar_withdraw_facts_record_id_fkey","validated":true,"definition":"FOREIGN KEY (record_id) REFERENCES newar_detail_records(id) ON UPDATE CASCADE ON DELETE CASCADE"}]},{"acl":"{postgres=arwdDxtm/postgres}","oid":"378192","rls":true,"kind":"r","owner":"postgres","table":"newar_withdraw_reason_facts","columns":[{"name":"amount","type":"numeric","default":null,"notNull":false},{"name":"created_at","type":"timestamp with time zone","default":null,"notNull":true},{"name":"display_state","type":"text","default":null,"notNull":false},{"name":"order_number","type":"text","default":null,"notNull":false},{"name":"platform","type":"text","default":null,"notNull":true},{"name":"received_at","type":"timestamp with time zone","default":null,"notNull":true},{"name":"record_id","type":"uuid","default":null,"notNull":true},{"name":"source_label","type":"text","default":null,"notNull":false}],"indexes":[{"ready":true,"valid":true,"unique":false,"definition":"CREATE INDEX newar_withdraw_reason_facts_platform_created_idx ON private.newar_withdraw_reason_facts USING btree (platform, created_at)"},{"ready":true,"valid":true,"unique":true,"definition":"CREATE UNIQUE INDEX newar_withdraw_reason_facts_pkey ON private.newar_withdraw_reason_facts USING btree (record_id)"}],"forceRls":false,"triggers":[],"qualified":"private.newar_withdraw_reason_facts","constraints":[{"name":"newar_withdraw_reason_facts_display_state_check","validated":true,"definition":"CHECK (((display_state IS NULL) OR (((length(display_state) >= 1) AND (length(display_state) <= 200)) AND (display_state !~ ''[[:cntrl:]]''::text))))"},{"name":"newar_withdraw_reason_facts_pkey","validated":true,"definition":"PRIMARY KEY (record_id)"},{"name":"newar_withdraw_reason_facts_record_id_fkey","validated":true,"definition":"FOREIGN KEY (record_id) REFERENCES newar_detail_records(id) ON UPDATE CASCADE ON DELETE CASCADE"},{"name":"newar_withdraw_reason_facts_source_label_check","validated":true,"definition":"CHECK (((source_label IS NULL) OR ((length(source_label) <= 256) AND (source_label !~ ''[[:cntrl:]]''::text))))"}]}]'::jsonb)LOOP
  SELECT *INTO c FROM pg_class WHERE oid=to_regclass(expected->>'qualified');
  IF c.oid IS NULL THEN RAISE EXCEPTION 'withdraw_reason_source_missing: %',expected->>'qualified';END IF;
  SELECT jsonb_build_object('qualified',expected->>'qualified','table',c.relname,'oid',c.oid::text,'acl',c.relacl::text,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'kind',c.relkind::text,
   'columns',coalesce((SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))ORDER BY a.attname COLLATE "C")
    FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'[]'),
   'indexes',coalesce((SELECT jsonb_agg(jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique)ORDER BY pg_get_indexdef(i.indexrelid)COLLATE "C")FROM pg_index i WHERE i.indrelid=c.oid),'[]'),
   'constraints',coalesce((SELECT jsonb_agg(jsonb_build_object('name',x.conname,'definition',pg_get_constraintdef(x.oid),'validated',x.convalidated)ORDER BY x.conname COLLATE "C")FROM pg_constraint x WHERE x.conrelid=c.oid),'[]'),
   'triggers',coalesce((SELECT jsonb_agg(jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled::text,'function',t.tgfoid::regprocedure::text,'functionBodyMd5',md5(p.prosrc),'functionDefinitionMd5',md5(pg_get_functiondef(p.oid)),'functionMetadata',to_jsonb(p)-'prosrc')ORDER BY pg_get_triggerdef(t.oid)COLLATE "C")FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND t.tgname NOT LIKE'reason_versions_%'),'[]'))INTO actual;
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'withdraw_reason_source_contract_drift: %',expected->>'qualified';END IF;
 END LOOP;
 PERFORM set_config('audit.withdraw_reason_source_cas','true',true);
END;$source_cas_post$;
DO $reason_after$
DECLARE v jsonb;proc_hash text;gens jsonb:='{}';sig text;value text;
BEGIN
 SELECT md5(coalesce(jsonb_agg(jsonb_build_array(p.oid,md5(p.prosrc),to_jsonb(p)-'prosrc')ORDER BY p.oid),'[]')::text)INTO proc_hash
 FROM pg_proc p WHERE p.pronamespace='private'::regnamespace AND p.proname NOT LIKE'withdraw_reason_%'AND p.oid<>ALL(ARRAY['private.withdraw_prepared_run_claimed()','private.withdraw_prepared_complete(jsonb,jsonb)','private.withdraw_prepared_maintenance()']::regprocedure[]);
 IF proc_hash IS DISTINCT FROM current_setting('audit.withdraw_reason_functions')THEN RAISE EXCEPTION'withdraw_reason_unrelated_function_changed';END IF;
 SELECT jsonb_agg(jsonb_build_array(c.oid,to_jsonb(c)-ARRAY['relhastriggers','relpages','reltuples','relallvisible'],
  (SELECT jsonb_agg(to_jsonb(a)ORDER BY attnum)FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0),
  (SELECT jsonb_agg(jsonb_build_array(t.oid,to_jsonb(t),pg_get_triggerdef(t.oid))ORDER BY t.oid)FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND t.tgname NOT LIKE'reason_versions_%'))ORDER BY c.oid)INTO v
 FROM pg_class c WHERE c.oid=ANY(ARRAY['public.ar_collected_orders','public.auto_withdraw_daily','public.newar_detail_records','private.newar_withdraw_facts','private.newar_withdraw_reason_facts','private.newar_detail_coverage_runs','private.ar_withdraw_detail_operator_evidence','public.newar_detail_platforms']::regclass[]);
 IF v::text IS DISTINCT FROM current_setting('audit.withdraw_reason_sources')THEN RAISE EXCEPTION'withdraw_reason_source_schema_or_existing_trigger_changed';END IF;
 FOR sig IN SELECT unnest(ARRAY['private.ar_withdraw_detail_evidence_generation()','private.ar_withdraw_fact_generation()','private.ar_historical_duration_generation()'])LOOP
  IF to_regprocedure(sig)IS NOT NULL THEN EXECUTE'SELECT '||sig INTO value;gens:=gens||jsonb_build_object(sig,value);END IF;
 END LOOP;
 IF gens::text IS DISTINCT FROM current_setting('audit.withdraw_reason_generations')THEN RAISE EXCEPTION'withdraw_reason_existing_generation_changed';END IF;
 IF jsonb_build_array(private.withdraw_prepared_dependency(),private.prepared_aggregate_dependency_common('IN'),
  (SELECT md5(coalesce(jsonb_agg(jsonb_build_array(to_jsonb(p),private.provider_snapshot_dependency_token(to_jsonb(p)))ORDER BY p.id),'[]')::text)FROM private.prepared_aggregate_native_catalog()p WHERE p.country='印度'AND p.source IN('ar','newar')))::text IS DISTINCT FROM current_setting('audit.withdraw_reason_dependencies')THEN RAISE EXCEPTION'withdraw_reason_existing_financial_dependencies_changed';END IF;
END;$reason_after$;

COMMIT;
